"use strict";(self.webpackChunkdocs_scadys_io=self.webpackChunkdocs_scadys_io||[]).push([["5837"],{3305(e){e.exports=JSON.parse('{"version":{"pluginId":"wti400-v12","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"wti400Sidebar":[{"type":"link","href":"/wti400/v1.2/","label":"WTI400 Overview (v1.2)","docId":"index","unlisted":false},{"type":"link","href":"/wti400/v1.2/quick-reference","label":"Quick Reference","docId":"quick-reference","unlisted":false},{"type":"link","href":"/wti400/v1.2/tasks","label":"Tasks","docId":"tasks","unlisted":false},{"type":"category","label":"Circuit Design","items":[{"type":"link","href":"/wti400/v1.2/circuit-design/esp32-module","label":"ESP32 Module","docId":"circuit-design/esp32-module","unlisted":false},{"type":"link","href":"/wti400/v1.2/circuit-design/programming-socket","label":"Programming Socket","docId":"circuit-design/programming-socket","unlisted":false},{"type":"link","href":"/wti400/v1.2/circuit-design/power-supplies","label":"Power Supply","docId":"circuit-design/power-supplies","unlisted":false},{"type":"link","href":"/wti400/v1.2/circuit-design/can-bus-power","label":"CAN Bus Power","docId":"circuit-design/can-bus-power","unlisted":false},{"type":"link","href":"/wti400/v1.2/circuit-design/can-transceiver","label":"CAN Transceiver","docId":"circuit-design/can-transceiver","unlisted":false},{"type":"link","href":"/wti400/v1.2/circuit-design/wind-interface","label":"Wind Interface","docId":"circuit-design/wind-interface","unlisted":false},{"type":"link","href":"/wti400/v1.2/circuit-design/motion-sensor","label":"Motion Sensor","docId":"circuit-design/motion-sensor","unlisted":false},{"type":"link","href":"/wti400/v1.2/circuit-design/button","label":"Button Input","docId":"circuit-design/button","unlisted":false},{"type":"link","href":"/wti400/v1.2/circuit-design/led-indicator","label":"LED Indicator","docId":"circuit-design/led-indicator","unlisted":false},{"type":"link","href":"/wti400/v1.2/circuit-design/legacy-serial","label":"Legacy Serial Interface","docId":"circuit-design/legacy-serial","unlisted":false},{"type":"link","href":"/wti400/v1.2/circuit-design/pcb-markings","label":"PCB Markings & Compliance","docId":"circuit-design/pcb-markings","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/wti400/v1.2/circuit-design/"},{"type":"category","label":"Firmware","items":[{"type":"link","href":"/wti400/v1.2/firmware/","label":"Firmware","docId":"firmware/index","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Housing","items":[{"type":"link","href":"/wti400/v1.2/housing/","label":"Housing","docId":"housing/index","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Compliance","items":[{"type":"link","href":"/wti400/v1.2/compliance/","label":"Compliance","docId":"compliance/index","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"circuit-design/button":{"id":"circuit-design/button","title":"Button Input","description":"WTI400 v1.2 \u2014 In service \u2014 installed on test vessel","sidebar":"wti400Sidebar"},"circuit-design/can-bus-power":{"id":"circuit-design/can-bus-power","title":"CAN Bus Power","description":"WTI400 v1.2 \u2014 In service \u2014 installed on test vessel","sidebar":"wti400Sidebar"},"circuit-design/can-transceiver":{"id":"circuit-design/can-transceiver","title":"CAN Transceiver","description":"WTI400 v1.2 \u2014 In service \u2014 installed on test vessel","sidebar":"wti400Sidebar"},"circuit-design/esp32-module":{"id":"circuit-design/esp32-module","title":"ESP32 Module","description":"WTI400 v1.2 \u2014 In service on the test vessel. Approximately 1,000 sea miles accumulated with the ESP32 continuously Wi-Fi-active. Self-calibrating firmware running, I2C bus at Standard mode (100 kHz). The firmware carries hard-coded start-up speed-conversion and installation-angle constants and hard-coded initial WINDX / WINDY ADC limits; the limits and midpoint are then self-adjusted at run-time as new extremes are observed. Subjective in-service performance is satisfactory; the Testing & Verification section lists what\'s still to be measured.","sidebar":"wti400Sidebar"},"circuit-design/index":{"id":"circuit-design/index","title":"Circuit Design","description":"WTI400 v1.2 \u2014 In service on the test vessel. The board has accumulated approximately 1,000 sea miles with the ESP32 continuously Wi-Fi-active and the wind transducer running on a self-calibrating firmware. The WTI400 is an evolution of the MLI400 V1.0 (Marine Legacy Interface) which carried a wind interface and a fairly mature bespoke firmware; the MLI400 V1.0 was installed on the same test vessel during the circumnavigation, accumulating thousands of sea miles in service and feeding the design improvements that produced V1.2. Subjective in-service performance is satisfactory; the per-circuit pages list the quantitative bench measurements still required.","sidebar":"wti400Sidebar"},"circuit-design/led-indicator":{"id":"circuit-design/led-indicator","title":"LED Indicator","description":"WTI400 v1.2 \u2014 In service \u2014 installed on test vessel","sidebar":"wti400Sidebar"},"circuit-design/legacy-serial":{"id":"circuit-design/legacy-serial","title":"Legacy Serial Interface","description":"WTI400 v1.2 \u2014 In service \u2014 installed on test vessel","sidebar":"wti400Sidebar"},"circuit-design/motion-sensor":{"id":"circuit-design/motion-sensor","title":"Motion Sensor","description":"WTI400 v1.2 \u2014 In service \u2014 installed on test vessel","sidebar":"wti400Sidebar"},"circuit-design/pcb-markings":{"id":"circuit-design/pcb-markings","title":"PCB Markings & Compliance","description":"WTI400 v1.2 \u2014 In service on the test vessel. The silkscreen marks, fiducials, and stackup documented here are as-built on the V1.2 boards deployed on the test vessel. Compliance-mark content is locked (the marks correspond to the EU RED 2014/53/EU, FCC Part 15, UKCA, RoHS, and China EFUP regulatory frameworks the WTI400 is targeted at), but final compliance-test confirmation (the test report that authorises affixing the CE / UKCA / FCC marks) is itself a V1.3 milestone \u2014 see the V1.3 backlog below.","sidebar":"wti400Sidebar"},"circuit-design/power-supplies":{"id":"circuit-design/power-supplies","title":"Power Supply","description":"WTI400 v1.2 \u2014 In service \u2014 installed on test vessel","sidebar":"wti400Sidebar"},"circuit-design/programming-socket":{"id":"circuit-design/programming-socket","title":"Programming Socket","description":"WTI400 v1.2 \u2014 In service on the test vessel. The page covers the developer/kit assembly variant currently fitted (U4 / D4 / D5 / J1 populated, R24 DNP); the Production variant section below describes the configuration the same PCB will carry once volume builds use the pogo-pin fixture.","sidebar":"wti400Sidebar"},"circuit-design/wind-interface":{"id":"circuit-design/wind-interface","title":"Wind Interface","description":"WTI400 v1.2 \u2014 In service on the test vessel. Approximately 1,000 sea miles accumulated with basic self-calibrating firmware. Subjective in-service performance satisfactory; no quantitative bench measurements yet for angle accuracy, ADC clipping, atan2 reconstruction, speed-pulse PPR, VAS rail under load, or LP2951 thermal soak. The Testing & Verification section lists the measurements required.","sidebar":"wti400Sidebar"},"compliance/index":{"id":"compliance/index","title":"Compliance","description":"{/ AI_CONTENT_PENDING /}","sidebar":"wti400Sidebar"},"firmware/index":{"id":"firmware/index","title":"Firmware","description":"{/ AI_CONTENT_PENDING /}","sidebar":"wti400Sidebar"},"housing/index":{"id":"housing/index","title":"Housing","description":"{/ AI_CONTENT_PENDING /}","sidebar":"wti400Sidebar"},"index":{"id":"index","title":"WTI400 Overview","description":"WTI400 v1.2 \u2014 In service \u2014 installed on test vessel","sidebar":"wti400Sidebar"},"quick-reference":{"id":"quick-reference","title":"Quick Reference","description":"WTI400 v1.2 \u2014 In service \u2014 installed on test vessel","sidebar":"wti400Sidebar"},"tasks":{"id":"tasks","title":"Tasks","description":"WTI400 v1.2 \u2014 In service on the test vessel (~1,000 sea miles). Live task list for the WTI400 V1.2 hardware revision and the next-version (V1.3 and V2.0) backlog. The board has been working in service for over a year; most verification tasks are quantitative bench measurements that haven\'t been performed against the in-service installation. Underlying data: tasks.json \u2014 hand-maintained, edited as work progresses.","sidebar":"wti400Sidebar"},"transducer-compatibility":{"id":"transducer-compatibility","title":"Transducer Compatibility Reference","description":"WTI400 v1.2 \u2014 In service on the test vessel. This reference applies to the V1.2 hardware as fitted; see the Wind Interface page for the V1.2 limitation that restricts the X / Y amplifier to the Raymarine 8v4 setpoint."}}}}')}}]);